def gemm_flops(m, k, n):
    return 2 * m * n * k

for m in (1, 32, 256):
    flops = gemm_flops(m, 768, 768)
    print(f"lot de {m:>3} : {flops:>15,} FLOPs")

def gemm_intensity(m, k, n, bytes_per_value=2):
    flops = 2 * m * n * k
    weights = n * k * bytes_per_value
    activations = (m * k + m * n) * bytes_per_value
    return flops / (weights + activations)

for m in (1, 32, 1024):
    print(f"lot de {m:>4} : {gemm_intensity(m, 4096, 4096):8.1f} FLOP/octet")
